function Intersperse(numbers: array of integer; delimeter: integer): array of integer;
begin
  var count := 0;
  Result := new integer[numbers.Length * 2 - 1];
  for var i := 0 to numbers.Length - 1 do
  begin
    Result[count] := numbers[i];
    count += 1;
    if i <> numbers.Length - 1 then
    begin
      Result[count] := delimeter;
      count += 1;
    end;
  end;
end;


function ParseNestedParens(parenString: string): array of integer;
begin
  Result := new integer[parenString.Length];
  var (i, maxLevel, level) := (0, 0, 0);
  foreach var c in parenString.ToCharArray do
  begin
    if c = '(' then
    begin
      level += 1;
      if level > maxLevel then
        maxLevel += 1;
    end
    else if c = ')' then
      level -= 1;
    Result[i] := level;
    i += 1;
  end;
end;


