function MakePalindrome(str: string): string;
begin
  var (i, j) := (0, 0);
  while j < str.Length - 1 do
  begin
    if str[i] = str[j + 1] then
      j += 1;
    if str[i + 1] = str[j + 1] then
      i += 1;
  end;
  Result := str.Substring(0, i + 1) + ReverseString(str.Substring(0, i + 1));
end;


