    begin
      min2 := min1;
      min1 := numbers[i];
    end
    else if numbers[i] < min2 then
      min2 := numbers[i];
  end;
  Result := (min1, min2)
end;


function RescaleToUnit(numbers : array of real): array of real;
begin
  var min := numbers[0];
  var max := numbers[0];
  for var i := 1 to numbers.Length - 1 do
  begin
    if numbers[i] < min then
      min := numbers[i];
    if numbers[i] > max then
      max := numbers[i];
  end;
  var range := max - min;
  for var i := 0 to numbers.Length - 1 do
    numbers[i] := (numbers[i] - min) / range;
  Result := numbers;
end;


