function Factorize(n: integer): array of integer;
begin
  Result := [];
  var (i, prime) := (2, 1);
  while Sqr(prime) <= n do
  begin
    while n mod prime = 0 do
    begin
      Result.Add(prime);
      n := n div prime
    end;
    i += 1;
    prime := i
  end;
  if n > 1 then
    Result.Add(n)
end;


