function ChangeBase(x: integer; base: integer): string;
begin
  if not (base in 2..9) then
    raise new System.ArgumentException('base must be in [2..9]');
  Result := '';
  while x > 0 do
  begin
    Result += char('0' + (x mod base));
    x := x div base
  end;
  Result := Result.Inverse
end;


