function Fib4(n: integer): integer;
begin
  if n < 0 then
    raise new System.ArgumentException('n must be >= 0');
  if n = 0 then
    Result := 0
  else if n = 1 then
    Result := 0
  else if n = 2 then
    Result := 2
  else if n = 3 then
    Result := 0
  else
  begin
    var a := 0;
    var b := 0;
    var c := 0;
    var d := 2;
    for var i := 4 to n do
    begin
      a := b;
      b := c;
      c := d;
      d += a + b + c;
    end;
    Result := d;
  end;
end;


