    Result := sb2.ToString = text;
  end
  else
    Result := True;
end;


function Modp(n: integer; p: integer): integer;
begin
  Result := 1;
  if n < 0 then
    n := -n;
  if p = 1 then
    exit(0);
  if p = 0 then
  begin
    Result := 0;
    exit;
  end;
  if n mod p = 0 then
    exit(0);
  while n mod p <> 0 do
  begin
    Result := Result * 2 mod p;
    n := n div p
  end;
  Result := Result * Power(2, n div p) mod p
end;

function EncodeShift(s : string): string;
{ returns encoded string by shifting every character by 5 in the alphabet. }
begin
  Result := '';
  for var i := 1 to s.Length do
  begin
    var ch := s[i];
    Result += Chr(((Ord(ch) + 5 - Ord('a')) mod 26) + Ord('a'));
  end;
end;
function DecodeShift(s : string): string;
{ takes as input string encoded with encode_shift function. Returns decoded string. }
begin
  Result := '';
  for var i := 1 to s.Length do
  begin
    var ch := s[i];
    Result += Chr(((Ord(ch) - Ord('a')) mod 26) + Ord('a'));
  end;
end;


