function Exchange(lst1, lst2: array of integer): string;
begin
  var (count1, count2) := (0, 0);
  for var i := 0 to lst1.Length - 1 do
    if lst1[i] mod 2 = 0 then
      count1 += 1
    else if lst2[i] mod 2 = 0 then
      count2 += 1
    else Result := 'NO';
  if (count1 = 0) and (count2 <> lst2.Length) then
    Result := 'YES'
  else Result := 'NO'
end;


function Histogram(test: string): Dictionary<string, integer>;
begin
  var s := test.Split(' ');
  var d := new Dictionary<string, integer>();
  foreach var x in s do
    if d.ContainsKey(x) then
      d[x] := d[x] + 1
    else d[x] := 1;
  var max := d.Max(x -> x.Value);
  d.Where(x -> x.Value = max).Keys.ToList.ForEach(k -> d[k] := max);
  Result := d;
end;


function ReverseDelete(s, c : string): (string, boolean);
