function Minsubarraysum(nums: array of integer): integer;
begin
  Result := integer.MaxValue;
  var n := nums.Length;
  for var i := 0 to n - 1 do
    for var j := i to n - 1 do
    begin
      var sum := 0;
      for var k := i to j do
        sum += nums[k];
      Result := min(Result, sum);
    end;
end;


function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var n := grid.Length;
  var m := grid[0].Length;
  var res := 0;
  for var i := 0 to n - 1 do
    for var j := 0 to m - 1 do
      if grid[i][j] = 1 then
        res += 1;
  var cnt := 0;
  for var i := 0 to n - 1 do
    for var j := 0 to m - 1 do
      if grid[i][j] = 1 then
      begin
        cnt += 1;
        if cnt = capacity then
        begin
          cnt := 0;
          res += 1;
        end;
      end
      else cnt := 0;
  Result := res;
end;


