function IsNested(s: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var c in s do
  begin
    if c = '[' then
      stack.Push(c)
    else if c = ']' then
    begin
      if stack.Count = 0 then
        Result := False
      else
      begin
        stack.Pop;
        if stack.Count <> 0 then
          Result := True
        else
        begin
          while stack.Count <> 0 do
          begin
            c := stack.Pop;
            if c <> '[' then
              break;
          end;
          if stack.Count = 0 then
            Result := True
          else
            stack.Pop;
        end;
      end;
    end;
  end;
  if stack.Count <> 0 then
    Result := False;
end;


