function FixSpaces(text: string): string;
begin
  var sb := new StringBuilder();
  var i := 0;
  while i < text.Length do
  begin
    if text[i] = ' ' then
    begin
      if sb.Length > 0 then
        sb.Append('_')
      else
        sb.Append(' ');
      Inc(i);
      continue;
    end;
    if text[i] = '  ' then
    begin
      if sb.Length > 0 then
        sb.Append('-')
      else
        sb.Append('  ');
      Inc(i);
      continue;
    end;
    sb.Append(text[i]);
    Inc(i);
  end;
  Result := sb.ToString();
end;


