    while number >= ar[i] do
    begin
      number -= ar[i];
      roman += ar2[i];
    end;
  end;
  Result := roman;
end;


function RightAngleTriangle(a, b, c: integer): boolean;
begin
  Result := (a * a + b * b = c * c) or (b * b + c * c = a * a) or (c * c + a * a = b * b);
end;


function FindMax(words: array of string): string;
begin
  var maxCount := -1;
  var maxWord := '';
  foreach var word in words do
  begin
    var count := word.ToCharArray.Distinct.Count;
    if count > maxCount then
    begin
      maxCount := count;
      maxWord := word;
    end
    else if count = maxCount then
      if word.CompareTo(maxWord) < 0 then
        maxWord := word;
  end;
  Result := maxWord;
end;


function Eat(number, need, remaining: integer): (integer, integer);
begin
  if number >= need then
    Result := (number + remaining, 0)
  else
  begin
    Result := (number + remaining, need - number);
  end;
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var ind := 0;
  Result := operand[0];
  for ind := 1 to operand.Length - 1 do
  begin
    case op[ind - 1] of
      '+': Result += operand[ind];
      '-': Result -= operand[ind];
      '*': Result *= operand[ind];
      '//': Result := Trunc(Result / operand[ind]);
      '**': Result := Power(Result, operand[ind]);
    end;
  end;
end;


function Solve(s: string): string;
begin
  var sb := new StringBuilder;
  foreach var c in s do
  begin
    if char.IsLetter(c) then
      sb.Append(char.IsUpper(c) ? char.ToLower(c) : char.ToUpper(c))
    else sb.Append(c)
  end;
  Result := sb.ToString.ToLower;
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
    Result := nil
  else Result := System.Security.Cryptography.MD5.Create().ComputeHash(Encoding.Default.GetBytes(text)).Aggregate('', (s, t) -> s + t.ToString('x'));
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  Result := [];
  if a > b then
    Swap(a, b);
  if a mod 2 = 0 then
    a += 1;
  if b mod 2 <> 0 then
    b -= 1;
  Result := Arr(a..b step 2);
end;
